// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (caller), v (value), tosLength (length of _tos array)
    function testFuzz_property(address from, uint256 v, uint256 tosLength) public {
        // keep tosLength in a reasonable wide bound but >=1 because function requires _tos.length>0
        uint256 len = bound(tosLength, 1, 8);

        // build _tos array of len entries. Use this contract as the callee target that always succeeds.
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(this); // this contract will accept calls and return successfully
        }

        // The rule: when transfer completes (does not revert), it returns true in the correct contract.
        // We call via try/catch to capture whether it reverted and capture the return value when available.

        bool ok;
        bool ret;
        try c.transfer(from, address(this), tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The single assertion: if the call completed (ok == true) then it must have returned true.
        // This is a universal property the reference satisfies for all admissible inputs, and the mutant
        // that returns false after success will violate it for some inputs (the fuzzer will find one).
        assertTrue(!ok || ret);
    }
}

// Minimal callee: accept arbitrary low-level calls and succeed
contract CalleeReceiver {
    // accept any call and return true-sized success
    fallback() external payable {}
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A minimal helper callee that emulates a successful transferFrom: it simply provides
    // a function matching the selector transferFrom(address,address,uint256) and returns true implicitly.
    // This ensures the low-level call in C succeeds for non-empty _tos.
    contract SuccessfulCallee {
        // matches transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // fuzzed params: from actor, callee address (we'll deploy a helper and use its address),
    // number of tos and a value. We must include at least one fuzz param; include multiple so fuzzer can find distinguishing input.
    function testFuzz_property(address from, uint8 tosCount, uint256 v) public {
        // keep tosCount reasonable but allow zero (the contract requires >0 so we must exclude zero)
        // bound tosCount to [0, 5] to let fuzzer pick small arrays; we will assume >0 below
        tosCount = uint8(bound(tosCount, 0, 5));
        vm.assume(tosCount > 0);

        // deploy a helper that will succeed on calls
        SuccessfulCallee helper = new SuccessfulCallee();
        address caddress = address(helper);

        // build a dynamic _tos array of length tosCount with arbitrary addresses derived from `from` and v
        address[] memory _tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // create varied addresses using hash so fuzzer influences them via `from` and loop index
            _tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Call transfer and capture whether it completed (did not revert) and the returned value.
        bool ok;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false; // irrelevant when reverted
        }

        // The universal property: whenever the call completes (ok == true), the reference implementation
        // must return true. The mutant that returns `!true` would return false while still completing,
        // so the single assertion below holds for the reference for all inputs and is violated by the mutant
        // for some inputs the fuzzer will find (any input that completes).
        assertTrue(!ok || ret);
    }
}

// Minimal helper defined after InvMutTest (as required).
contract SuccessfulCallee {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
